css:
/* ==========================================================================
   KHO PHIM TV - SMART TV EDITION STYLESHEET (10-Foot UI for 1080p & 4K)
   Pure Netflix Layout: Left Sidebar + Billboard + Dynamic Horizontal Shelves
   ========================================================================== */

:root {
  --bg-primary: #0F0F0F;
  --bg-sidebar: #090909;
  --bg-card: #181818;
  --accent-red: #E50914;
  --accent-red-hover: #b80710;
  --text-white: #FFFFFF;
  --text-muted: #888888;
  --sidebar-collapsed-width: 68px;
  --sidebar-expanded-width: 230px;
}

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background-color: var(--bg-primary);
  color: var(--text-white);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  user-select: none !important;
  -webkit-user-select: none !important;
  cursor: none !important; /* Hide mouse completely on TV */
}

/* Base App Layout */
#tv-app {
  display: flex;
  width: 100vw;
  height: 100vh;
  position: relative;
  overflow: hidden;
}

/* ==========================================================================
   NETFLIX LEFT EXPANDABLE SIDEBAR
   ========================================================================== */
.tv-sidebar {
  position: relative;
  width: var(--sidebar-collapsed-width);
  height: 100vh;
  background: linear-gradient(to right, rgba(9, 9, 9, 0.98), rgba(15, 15, 15, 0.9));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 24px 10px;
  z-index: 100;
  transition: width 0.16s ease-out;
  overflow: hidden;
  border-right: 1px solid rgba(255, 255, 255, 0.05);
}

.tv-sidebar.expanded,
.tv-sidebar:focus-within {
  width: var(--sidebar-expanded-width);
  background: linear-gradient(to right, rgba(9, 9, 9, 1), rgba(12, 12, 12, 0.98));
  box-shadow: 12px 0 32px rgba(0, 0, 0, 0.8);
}

.sidebar-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 4px 6px 28px 6px;
  white-space: nowrap;
}

.sidebar-logo-icon {
  width: 38px;
  height: 38px;
  border-radius: 8px;
  flex-shrink: 0;
}

.sidebar-logo-text {
  font-size: 19px;
  font-weight: 900;
  color: var(--accent-red);
  letter-spacing: 1px;
  opacity: 0;
  transition: opacity 0.14s ease-out;
}

.tv-sidebar.expanded .sidebar-logo-text,
.tv-sidebar:focus-within .sidebar-logo-text {
  opacity: 1;
}

.sidebar-menu {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sidebar-item {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 48px;
  padding: 0 14px;
  border-radius: 8px;
  color: var(--text-muted);
  cursor: pointer;
  white-space: nowrap;
  outline: none;
  transition: background 0.1s ease-out, color 0.1s ease-out;
}

.sidebar-icon {
  width: 24px;
  height: 24px;
  fill: currentColor;
  flex-shrink: 0;
}

.sidebar-label {
  font-size: 15px;
  font-weight: 600;
  opacity: 0;
  transition: opacity 0.14s ease-out;
}

.tv-sidebar.expanded .sidebar-label,
.tv-sidebar:focus-within .sidebar-label {
  opacity: 1;
}

.sidebar-item.active {
  color: var(--accent-red);
  background: rgba(229, 9, 20, 0.15);
}

/* Netflix Style: Focused sidebar tab turns crisp white with black text */
.sidebar-item.tv-focused {
  background: #FFFFFF !important;
  color: #000000 !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5) !important;
  transform: scale(1.04) translateZ(0) !important;
}

.sidebar-item.tv-focused .sidebar-icon {
  fill: #000000 !important;
}

.sidebar-item.tv-focused .sidebar-label {
  font-weight: 800 !important;
  color: #000000 !important;
}

/* ==========================================================================
   MAIN CONTENT VIEWPORT
   ========================================================================== */
.tv-main-content {
  flex: 1;
  height: 100vh;
  overflow-y: auto;
  overflow-x: hidden;
  position: relative;
  scrollbar-width: none;
  scroll-behavior: auto !important; /* Instant snap scroll */
}

.tv-main-content::-webkit-scrollbar {
  display: none;
}

.tv-view {
  display: none;
  min-height: 100vh;
  padding-bottom: 60px;
}

.tv-view.active {
  display: block;
}

/* ==========================================================================
   BILLBOARD HERO BANNER
   ========================================================================== */
.tv-hero-banner {
  position: relative;
  width: 100%;
  height: 480px;
  background-size: cover;
  background-position: center top;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 40px 52px;
  margin-bottom: 24px;
}

.tv-hero-banner::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(15, 15, 15, 0.1) 0%,
    rgba(15, 15, 15, 0.6) 45%,
    var(--bg-primary) 100%
  ),
  linear-gradient(
    to right,
    rgba(15, 15, 15, 0.95) 0%,
    rgba(15, 15, 15, 0.4) 60%,
    transparent 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 720px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hero-badge-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.hero-badge {
  font-size: 13px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.2);
  color: #fff;
  padding: 3px 8px;
  border-radius: 4px;
}

.hero-badge.red {
  background: var(--accent-red);
}

.hero-title {
  font-size: 38px;
  font-weight: 900;
  line-height: 1.15;
  text-shadow: 0 3px 8px rgba(0, 0, 0, 0.8);
}

.hero-overview {
  font-size: 15px;
  line-height: 1.45;
  color: #D1D1D1;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.8);
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 8px;
}

/* ==========================================================================
   BUTTONS (TV SIZED)
   ========================================================================== */
.tv-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  font-size: 16px;
  font-weight: 700;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  outline: none;
  transition: transform 0.1s ease-out;
  transform: translateZ(0);
}

.tv-btn svg {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

.tv-btn-primary {
  background: var(--accent-red);
  color: #FFFFFF;
}

.tv-btn-secondary {
  background: rgba(255, 255, 255, 0.18);
  color: #FFFFFF;
}

.tv-btn.tv-focused {
  background: #FFFFFF !important;
  color: #000000 !important;
  transform: scale(1.08) translateZ(0) !important;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.8), 0 0 12px rgba(255, 255, 255, 0.8) !important;
}

.tv-btn.tv-focused svg {
  fill: #000000 !important;
}

/* ==========================================================================
   SHELVES & HORIZONTAL ROWS
   ========================================================================== */
/* ==========================================================================
   SHELVES & HORIZONTAL ROWS
   ========================================================================== */
.tv-shelf-section {
  margin-bottom: 34px;
}

.shelf-title {
  font-size: 20px;
  font-weight: 800;
  color: #E5E5E5;
  padding: 0 52px 10px 52px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.shelf-more-badge {
  color: #54B9C5;
  font-size: 18px;
  font-weight: 800;
}

.tv-shelf-row {
  display: flex;
  gap: 14px;
  padding: 18px 52px 26px 52px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  scroll-behavior: auto !important; /* Instant snap scroll */
  position: relative;
}

.tv-shelf-row::-webkit-scrollbar {
  display: none;
}

.tv-shelf-row::after {
  content: "";
  flex: 0 0 52px;
  width: 52px;
}

/* Movie Card - Exact Android TV TvCard.kt match */
.tv-card {
  flex: 0 0 152px;
  width: 152px;
  cursor: pointer;
  outline: none;
  transition: transform 0.12s ease-out, border 0.12s ease-out, box-shadow 0.12s ease-out;
  transform: translateZ(0);
  will-change: transform;
  position: relative;
  background-color: #1F1F1F;
  border-radius: 6px;
  border: 0.5px solid rgba(255, 255, 255, 0.12);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.tv-card-poster-wrap {
  position: relative;
  width: 100%;
  height: 212px;
  overflow: hidden;
  background-color: #141414;
}

.tv-card-poster-wrap::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 55%, rgba(0, 0, 0, 0.85) 100%);
  pointer-events: none;
}

.tv-card-poster-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.tv-badge-left {
  position: absolute;
  top: 5px;
  left: 5px;
  background: rgba(0, 0, 0, 0.8);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  padding: 2px 5px;
  border-radius: 2px;
  z-index: 2;
}

.tv-badge-right {
  position: absolute;
  top: 5px;
  right: 5px;
  background: var(--accent-red);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  padding: 2px 5px;
  border-radius: 2px;
  z-index: 2;
}

.tv-card-info {
  padding: 6px 8px 8px 8px;
  background-color: #1F1F1F;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.tv-card-title {
  font-size: 12px;
  font-weight: 500;
  color: #D1D1D1;
  line-height: 1.25;
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
}

.tv-card-meta {
  display: none;
  align-items: center;
  gap: 6px;
  margin-top: 3px;
}

.tv-card-match {
  color: #46D369;
  font-size: 10px;
  font-weight: 800;
}

.tv-card-hd {
  color: #A3A3A3;
  font-size: 9px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.12);
  padding: 1px 4px;
  border-radius: 2px;
}

/* Card Focused: 1.15x scale, 2.5px solid white border, elevated shadow */
.tv-card.tv-focused {
  transform: scale(1.15) translateZ(0) !important;
  border: 2.5px solid #FFFFFF !important;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.95), 0 0 16px rgba(255, 255, 255, 0.45) !important;
  z-index: 40 !important;
}

.tv-card.tv-focused .tv-card-title {
  color: #FFFFFF !important;
  font-weight: 700 !important;
}

.tv-card.tv-focused .tv-card-meta {
  display: flex !important;
}

/* Xem Thêm / Tải Thêm Phim Card at the end of each shelf row (matches TvShelfLoadMoreCard) */
.tv-card-more {
  flex: 0 0 152px;
  width: 152px;
  min-height: 256px;
  background-color: #1E1E1E;
  border: 0.5px solid rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  cursor: pointer;
  outline: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 16px 10px;
  transition: transform 0.12s ease-out, background 0.12s ease-out, border 0.12s ease-out;
  transform: translateZ(0);
  will-change: transform;
}

.tv-card-more-circle {
  width: 44px;
  height: 44px;
  border-radius: 22px;
  background: #333333;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  transition: background 0.12s ease-out;
}

.tv-card-more-circle svg {
  width: 24px;
  height: 24px;
  fill: #FFFFFF;
}

.tv-card-more-title {
  font-size: 13px;
  font-weight: 700;
  color: #FFFFFF;
  margin-bottom: 3px;
}

.tv-card-more-sub {
  font-size: 10px;
  color: var(--text-muted);
}

.tv-card-more.tv-focused {
  background: rgba(229, 9, 20, 0.35) !important;
  border: 2.5px solid #FFFFFF !important;
  transform: scale(1.15) translateZ(0) !important;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.95), 0 0 16px rgba(255, 255, 255, 0.45) !important;
  z-index: 40 !important;
}

.tv-card-more.tv-focused .tv-card-more-circle {
  background: var(--accent-red) !important;
}

.tv-card-more.loading .tv-card-more-circle {
  animation: spin 1s infinite linear;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* Continue Watching Card (Landscape 16:9) */
.tv-continue-card {
  flex: 0 0 280px;
  width: 280px;
  background-color: #1E1E1E;
  border: 0.5px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  cursor: pointer;
  outline: none;
  transition: transform 0.12s ease-out, border 0.12s ease-out, box-shadow 0.12s ease-out;
  transform: translateZ(0);
  will-change: transform;
  overflow: hidden;
}

.tv-continue-thumb-wrap {
  position: relative;
  width: 100%;
  height: 156px;
  overflow: hidden;
  background-color: #141414;
}

.tv-continue-thumb-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.tv-continue-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: rgba(255, 255, 255, 0.25);
}

.tv-continue-progress-bar {
  height: 100%;
  background: var(--accent-red);
}

.tv-continue-info {
  padding: 8px 10px;
  background-color: #1E1E1E;
}

.tv-continue-title {
  font-size: 13.5px;
  font-weight: 700;
  color: var(--text-white);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tv-continue-sub {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 2px;
}

.tv-continue-card.tv-focused {
  transform: scale(1.10) translateZ(0) !important;
  border: 2.5px solid #FFFFFF !important;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.95), 0 0 16px rgba(255, 255, 255, 0.45) !important;
  z-index: 40 !important;
}

.tv-continue-card.tv-focused .tv-continue-info {
  background-color: #262626 !important;
}

.tv-continue-card.tv-focused .tv-continue-title {
  color: #FFFFFF !important;
  font-weight: 800 !important;
}

/* ==========================================================================
   CATEGORY & SEARCH GRID (GRID VIEWS)
   ========================================================================== */
.view-title {
  font-size: 32px;
  font-weight: 900;
  color: var(--text-white);
}

.category-header,
.search-header,
.history-header {
  padding: 40px 52px 20px 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.tv-movie-grid,
.tv-history-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(155px, 1fr));
  gap: 20px;
  padding: 10px 52px 40px 52px;
}

.tv-movie-grid .tv-card {
  width: 100% !important;
  flex: none !important;
}

.load-more-wrap {
  text-align: center;
  padding: 20px 52px 40px 52px;
}

.tv-status-msg {
  padding: 20px 52px;
  font-size: 16px;
  color: var(--text-muted);
}

/* Search Input */
.search-input-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg-card);
  border: 2px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  padding: 12px 20px;
  width: 480px;
}

.search-input-wrap:focus-within {
  border-color: var(--accent-red);
}

.search-icon {
  width: 22px;
  height: 22px;
  fill: var(--text-muted);
}

.search-input-wrap input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  font-size: 17px;
  color: #FFFFFF;
  user-select: text !important;
  -webkit-user-select: text !important;
  cursor: text !important;
}

.tv-btn-clear {
  background: transparent;
  border: none;
  color: #fff;
  font-size: 16px;
  cursor: pointer;
}

/* Settings View */
.settings-wrap {
  padding: 40px 52px;
}

.settings-card {
  background: var(--bg-card);
  border-radius: 12px;
  padding: 24px;
  margin-top: 20px;
  max-width: 800px;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.settings-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
}

.settings-card p {
  font-size: 14px;
  color: var(--text-muted);
  line-height: 1.5;
}

.domain-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 14px;
}

.domain-pill {
  padding: 10px 20px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  outline: none;
}

.domain-pill.active {
  background: var(--accent-red);
  color: #fff;
}

.domain-pill.tv-focused {
  background: #FFFFFF !important;
  color: #000000 !important;
  transform: scale(1.05) translateZ(0) !important;
}

/* ==========================================================================
   DETAIL MODAL (10-FOOT CINEMATIC OVERLAY)
   ========================================================================== */
.tv-detail-modal {
  position: fixed;
  inset: 0;
  background: var(--bg-primary);
  z-index: 200;
  display: none;
  overflow-y: auto;
  scrollbar-width: none;
}

.tv-detail-modal.open {
  display: block;
}

.tv-detail-backdrop {
  position: absolute;
  top: 0;
  right: 0;
  width: 75vw;
  height: 520px;
  background-size: cover;
  background-position: center top;
}

.tv-detail-gradient {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 520px;
  background: linear-gradient(to right, #0F0F0F 35%, rgba(15, 15, 15, 0.8) 60%, rgba(15, 15, 15, 0.2) 100%),
              linear-gradient(to bottom, transparent 60%, #0F0F0F 100%);
}

.tv-detail-content {
  position: relative;
  z-index: 5;
  padding: 60px 80px 80px 80px;
  max-width: 880px;
}

.detail-title {
  font-size: 46px;
  font-weight: 900;
  line-height: 1.15;
  margin-bottom: 14px;
}

.detail-meta-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.detail-badge {
  font-size: 13px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.2);
  color: #fff;
  padding: 3px 8px;
  border-radius: 4px;
}

.detail-badge-red {
  background: var(--accent-red);
}

.detail-meta-text {
  font-size: 14px;
  color: var(--text-muted);
}

.detail-overview {
  font-size: 16px;
  line-height: 1.5;
  color: #C0C0C0;
  margin-bottom: 24px;
}

.detail-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 36px;
}

.tv-episodes-section {
  margin-top: 24px;
}

.tv-server-tabs {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
  overflow-x: auto;
}

.tv-server-pill {
  padding: 10px 22px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  outline: none;
}

.tv-server-pill.active {
  background: var(--accent-red);
  color: #fff;
}

.tv-server-pill.tv-focused {
  background: #FFFFFF !important;
  color: #000000 !important;
  transform: scale(1.06) translateZ(0) !important;
}

.tv-episode-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(95px, 1fr));
  gap: 12px;
}

.tv-ep-btn {
  padding: 10px 0;
  text-align: center;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  color: #fff;
  cursor: pointer;
  outline: none;
  transition: transform 0.1s ease-out;
}

.tv-ep-btn.active {
  background: var(--accent-red);
}

.tv-ep-btn.tv-focused {
  background: #FFFFFF !important;
  color: #000000 !important;
  transform: scale(1.1) translateZ(0) !important;
  font-weight: 800 !important;
}

/* ==========================================================================
   TV VIDEO PLAYER OVERLAY
   ========================================================================== */
.tv-player-overlay {
  position: fixed;
  inset: 0;
  background: #000000;
  z-index: 500;
  display: none;
}

.tv-player-overlay.open {
  display: block;
}

#tv-video-player,
#tv-iframe-player {
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  object-fit: contain;
}

#tv-iframe-player {
  display: none;
}

.tv-player-hud {
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.8) 0%, transparent 25%, transparent 70%, rgba(0, 0, 0, 0.9) 100%);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 40px 60px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease-out;
}

.tv-player-hud.visible {
  opacity: 1;
  pointer-events: auto;
}

.player-top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
}

.player-title-box {
  display: flex;
  align-items: center;
}

.player-movie-title {
  font-size: 24px;
  font-weight: 800;
}

.player-ep-name {
  font-size: 16px;
  color: var(--accent-red);
  margin-left: 12px;
}

.player-source-box {
  display: flex;
  align-items: center;
}

.player-source-badge {
  background: rgba(255, 255, 255, 0.16);
  border: 1.5px solid rgba(255, 255, 255, 0.35);
  color: #fff;
  padding: 6px 18px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  outline: none;
  transition: transform 0.1s ease-out, background 0.1s ease-out;
}

.player-source-badge.tv-focused {
  background: #FFFFFF !important;
  color: #000000 !important;
  transform: scale(1.08) !important;
  box-shadow: 0 0 16px rgba(255, 255, 255, 0.9) !important;
}

/* TV Player Error & Fallback Modal */
.tv-player-error-modal {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.94);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 600;
  padding: 24px;
}

.player-error-content {
  max-width: 580px;
  text-align: center;
  background: #181818;
  border: 1.5px solid rgba(255, 255, 255, 0.15);
  border-radius: 12px;
  padding: 36px 32px;
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.9);
}

.player-error-icon {
  font-size: 48px;
  margin-bottom: 12px;
}

.player-error-title {
  font-size: 22px;
  font-weight: 800;
  color: #fff;
  margin-bottom: 10px;
}

.player-error-desc {
  font-size: 14px;
  color: #AAA;
  line-height: 1.5;
  margin-bottom: 24px;
}

.player-error-buttons {
  display: flex;
  gap: 14px;
  justify-content: center;
}

.player-progress-bar-wrap {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.25);
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 10px;
}

.player-progress-fill {
  width: 0%;
  height: 100%;
  background: var(--accent-red);
  transition: width 0.2s linear;
}

.player-time-row {
  display: flex;
  justify-content: space-between;
  font-size: 15px;
  font-weight: 600;
  color: #C0C0C0;
}

.player-help-hint {
  font-size: 13px;
  color: #888;
  margin-top: 10px;
  text-align: center;
}

/* ==========================================================================
   TV TOAST NOTIFICATION
   ========================================================================== */
.tv-toast {
  position: fixed;
  bottom: 48px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(18, 18, 18, 0.95);
  color: #fff;
  border: 1px solid rgba(229, 9, 20, 0.7);
  padding: 12px 28px;
  border-radius: 30px;
  font-size: 15px;
  font-weight: 600;
  z-index: 10000;
  display: none;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.9);
  pointer-events: none;
}

/* Provider rating: does not overlap quality/episode badges. */
.movie-rating{position:absolute;bottom:6px;left:6px;z-index:2;padding:3px 5px;border-radius:4px;background:rgba(0,0,0,.85);color:#ffd166;font-size:11px;font-weight:700;line-height:1.3;white-space:nowrap}
.movie-rating-detail{display:block;color:#ffd166;font-size:13px;line-height:1.5;margin:8px 0 16px}

